     3	/**
     4	 * A policy the office has issued: what it covers, and what is left of its cap.
     5	 *
     6	 * The cap is what the office will ever pay out on the policy, so it is consumed as claims
     7	 * are settled: a claim is paid only as far as the cap still reaches, and what it does not
     8	 * reach is not paid at all.
     9	 */
    10	public class Policy {
    11	
    12	    private final InsuredItems insuredItems;
    13	
    14	    private int remainingCap;
    15	
    16	    public Policy(List<Item> items) {
    17	        this.insuredItems = new InsuredItems(items);
    18	        this.remainingCap = insuredItems.cover().cap();
    19	    }
    20	
    21	    public InsuredItems insuredItems() {
    22	        return insuredItems;
    23	    }
    24	
    25	    public int settle(int desiredPayout) {
    26	        int payout = Math.min(desiredPayout, remainingCap);
    27	        remainingCap -= payout;
    28	        return payout;
    29	    }
    30	
    31	    public int remainingCap() {
    32	        return remainingCap;
    33	    }
