=== ItemRiskSurcharge.java ===
     1	/**
     2	 * The risk surcharges the office adds for a single insured item.
     3	 *
     4	 * A cursed item and a highly enchanted item each carry a risk surcharge on that item's
     5	 * own base premium, not on the premium of the whole policy. An item that is both carries
     6	 * both surcharges.
     7	 */
     8	public class ItemRiskSurcharge {
     9	
    10	    private final PriceList priceList = new PriceList();
    11	
    12	    public double forItem(Item item) {
    13	        double basePremium = priceList.basePremiumFor(item);
    14	        return basePremium * totalRateFor(item);
    15	    }
    16	
    17	    /**
    18	     * Each risk the office recognises is assessed on its own; an item that carries
    19	     * several risks carries the sum of their rates.
    20	     */
    21	    private double totalRateFor(Item item) {
    22	        double rate = 0;
    23	        for (RecognisedRisk risk : RecognisedRisk.values()) {
    24	            if (risk.isCarriedBy(item)) {
    25	                rate += risk.rate();
    26	            }
    27	        }
    28	        return rate;
    29	    }
    30	}
=== RecognisedRisk.java ===
     1	/**
     2	 * A risk the MHPCO recognises on a single insured item, and the surcharge rate it carries.
     3	 *
     4	 * The office's risk catalogue: each entry names one hazard, says when an item carries it,
     5	 * and at what rate. Revising a threshold or a rate is a change to one entry; recognising
     6	 * a new hazard is a new entry.
     7	 */
     8	public enum RecognisedRisk {
     9	
    10	    CURSE(0.50) {
    11	        @Override
    12	        boolean isCarriedBy(Item item) {
    13	            return item.cursed();
    14	        }
    15	    },
    16	
    17	    HIGH_ENCHANTMENT(0.30) {
    18	        /** The enchantment level from which the office surcharges a premium for risk. */
    19	        private static final int SURCHARGED_ENCHANTMENT_LEVEL = 5;
    20	
    21	        @Override
    22	        boolean isCarriedBy(Item item) {
    23	            return item.enchantment() >= SURCHARGED_ENCHANTMENT_LEVEL;
    24	        }
    25	    };
    26	
    27	    private final double rate;
    28	
    29	    RecognisedRisk(double rate) {
    30	        this.rate = rate;
    31	    }
    32	
    33	    abstract boolean isCarriedBy(Item item);
    34	
    35	    double rate() {
    36	        return rate;
    37	    }
    38	}

